"""
Form classes
"""

import asyncio
import copy
import datetime
import inspect

from django.core.exceptions import NON_FIELD_ERRORS, ValidationError
from django.forms.fields import Field
from django.forms.utils import ErrorDict, ErrorList, RenderableFormMixin
from django.forms.widgets import Media, MediaDefiningClass
from django.utils.datastructures import MultiValueDict
from django.utils.translation import gettext as _

from .renderers import get_default_renderer

__all__ = ("BaseForm", "Form")

# Marker for "cleaned_data was never populated" (accessing it raises
# AttributeError, as on a form that has never been validated).
_UNSET = object()


def _snapshot_mapping(mapping):
    """Return a detached shallow copy of a bound data/files mapping.

    ``MultiValueDict`` copies keep their multi-value semantics; the mapping
    setters replace per-key value lists rather than mutating them, so data
    rebound or changed after the snapshot was taken cannot reach the copy.
    Plain mappings are copied with ``dict()``.
    """
    if isinstance(mapping, MultiValueDict):
        return copy.copy(mapping)
    return dict(mapping)


def _mapping_fingerprint(mapping):
    """Build a value-based, order-preserving fingerprint of a mapping.

    Equality compares the contained values (``==``), so in-place mutations of
    bound data invalidate a cached validation round even when the mapping
    object's identity is unchanged.
    """
    if isinstance(mapping, MultiValueDict):
        return tuple((key, tuple(values)) for key, values in mapping.lists())
    return tuple((key, mapping[key]) for key in mapping)


class DeclarativeFieldsMetaclass(MediaDefiningClass):
    """Collect Fields declared on the base classes."""

    def __new__(mcs, name, bases, attrs):
        # Collect fields from current class and remove them from attrs.
        attrs["declared_fields"] = {
            key: attrs.pop(key)
            for key, value in list(attrs.items())
            if isinstance(value, Field)
        }

        new_class = super().__new__(mcs, name, bases, attrs)

        # Walk through the MRO.
        declared_fields = {}
        for base in reversed(new_class.__mro__):
            # Collect fields from base class.
            if hasattr(base, "declared_fields"):
                declared_fields.update(base.declared_fields)

            # Field shadowing.
            for attr, value in base.__dict__.items():
                if value is None and attr in declared_fields:
                    declared_fields.pop(attr)

        new_class.base_fields = declared_fields
        new_class.declared_fields = declared_fields

        return new_class


class _AsyncValidationState:
    """Bookkeeping for a single asynchronous validation round.

    Several concurrent ``BaseForm.ais_valid()`` calls share one state (and
    one runner task) so that side-effectful validators run only once per
    round.
    """

    def __init__(self, *, is_bound, inputs, fields, fingerprint):
        self.runner_task = None
        # Number of ais_valid() callers currently awaiting the runner task.
        self.waiters = 0
        # Set once the round has either completed or been abandoned.
        self.finalized = False
        # Whether the form was bound when the round started.
        self.is_bound = is_bound
        # Detached snapshots the round cleans against. Inputs rebound or
        # mutated after the round started never reach the runner.
        self.data = inputs[0]
        self.files = inputs[1]
        self.initial = inputs[2]
        self.fields = fields
        # BoundField objects private to the runner task; lazily cached
        # values (initial, subwidgets) are computed against the snapshot.
        self.bound_fields_cache = {}
        # Value-based fingerprint of the snapshot, used to decide whether a
        # later call can reuse the completed result.
        self.fingerprint = fingerprint
        # The last successfully completed state to roll back to if this
        # round is abandoned or dies on a non-ValidationError exception.
        self.previous_errors = None
        self.previous_cleaned_data = _UNSET
        # The business result of a completed round, shared with every waiter
        # so callers observe one identical conclusion even if the form is
        # re-validated or reset between the runner finishing and the waiters
        # resuming.
        self.result = None


class BaseForm(RenderableFormMixin):
    """
    The main implementation of all the Form logic. Note that this class is
    different than Form. See the comments by the Form class for more info. Any
    improvements to the form API should be made to this class, not to the Form
    class.
    """

    default_renderer = None
    field_order = None
    prefix = None
    use_required_attribute = True

    template_name_div = "django/forms/div.html"
    template_name_p = "django/forms/p.html"
    template_name_table = "django/forms/table.html"
    template_name_ul = "django/forms/ul.html"
    template_name_label = "django/forms/label.html"

    bound_field_class = None

    def __init__(
        self,
        data=None,
        files=None,
        auto_id="id_%s",
        prefix=None,
        initial=None,
        error_class=ErrorList,
        label_suffix=None,
        empty_permitted=False,
        field_order=None,
        use_required_attribute=None,
        renderer=None,
        bound_field_class=None,
    ):
        self.is_bound = data is not None or files is not None
        self._data = MultiValueDict() if data is None else data
        self._files = MultiValueDict() if files is None else files
        self.auto_id = auto_id
        if prefix is not None:
            self.prefix = prefix
        self._initial = initial or {}
        self.error_class = error_class
        # Translators: This is the default suffix added to form field labels
        self.label_suffix = label_suffix if label_suffix is not None else _(":")
        self.empty_permitted = empty_permitted
        self._errors = None  # Stores the errors after clean() has been called.
        # cleaned_data is only populated during a (a)full_clean(); before
        # that it raises AttributeError like a plain unset attribute.
        self._cleaned_data = _UNSET
        # State for an in-progress asynchronous validation round (ais_valid()).
        # None when no async round is running.
        self._async_validation = None
        # Fingerprint of the inputs/field definitions used by the last
        # successfully completed validation round, for reuse checks.
        self._validation_fingerprint = None

        # The base_fields class attribute is the *class-wide* definition of
        # fields. Because a particular *instance* of the class might want to
        # alter self.fields, we create self.fields here by copying base_fields.
        # Instances should always modify self.fields; they should not modify
        # self.base_fields.
        self._fields = copy.deepcopy(self.base_fields)
        self._bound_fields_cache = {}
        self.order_fields(self.field_order if field_order is None else field_order)

        if use_required_attribute is not None:
            self.use_required_attribute = use_required_attribute

        if self.empty_permitted and self.use_required_attribute:
            raise ValueError(
                "The empty_permitted and use_required_attribute arguments may "
                "not both be True."
            )

        # Initialize form renderer. Use a global default if not specified
        # either as an argument or as self.default_renderer.
        if renderer is None:
            if self.default_renderer is None:
                renderer = get_default_renderer()
            else:
                renderer = self.default_renderer
                if isinstance(self.default_renderer, type):
                    renderer = renderer()
        self.renderer = renderer

        self.bound_field_class = (
            bound_field_class
            or self.bound_field_class
            or getattr(self.renderer, "bound_field_class", None)
        )

    def order_fields(self, field_order):
        """
        Rearrange the fields according to field_order.

        field_order is a list of field names specifying the order. Append
        fields not included in the list in the default order for backward
        compatibility with subclasses not overriding field_order. If
        field_order is None, keep all fields in the order defined in the class.
        Ignore unknown fields in field_order to allow disabling fields in form
        subclasses without redefining ordering.
        """
        if field_order is None:
            return
        fields = {}
        for key in field_order:
            try:
                fields[key] = self.fields.pop(key)
            except KeyError:  # ignore unknown fields
                pass
        fields.update(self.fields)  # add remaining fields in original order
        self.fields = fields

    def __repr__(self):
        if self._errors is None:
            is_valid = "Unknown"
        else:
            is_valid = self.is_bound and not self._errors
        return "<%(cls)s bound=%(bound)s, valid=%(valid)s, fields=(%(fields)s)>" % {
            "cls": self.__class__.__name__,
            "bound": self.is_bound,
            "valid": is_valid,
            "fields": ";".join(self.fields),
        }

    def _bound_items(self):
        """Yield (name, bf) pairs, where bf is a BoundField object."""
        for name in self.fields:
            yield name, self[name]

    def __iter__(self):
        """Yield the form's fields as BoundField objects."""
        for name in self.fields:
            yield self[name]

    def __getitem__(self, name):
        """Return a BoundField with the given name."""
        state = self._async_validation
        if state is not None and asyncio.current_task() is state.runner_task:
            # The runner uses its own BoundField objects so lazily cached
            # values computed against the round snapshot never leak onto the
            # BoundFields shared with the outside world.
            cache = state.bound_fields_cache
            fields = state.fields
        else:
            cache = self._bound_fields_cache
            fields = self._fields
        try:
            field = fields[name]
        except KeyError:
            raise KeyError(
                "Key '%s' not found in '%s'. Choices are: %s."
                % (
                    name,
                    self.__class__.__name__,
                    ", ".join(sorted(fields)),
                )
            )
        if name not in cache:
            cache[name] = field.get_bound_field(self, name)
        return cache[name]

    @property
    def data(self):
        # The task running an asynchronous round reads from its detached
        # snapshot; everyone else reads the live bound data.
        state = self._async_validation
        if state is not None and asyncio.current_task() is state.runner_task:
            return state.data
        return self._data

    @data.setter
    def data(self, value):
        self._data = value

    @property
    def files(self):
        state = self._async_validation
        if state is not None and asyncio.current_task() is state.runner_task:
            return state.files
        return self._files

    @files.setter
    def files(self, value):
        self._files = value

    @property
    def initial(self):
        state = self._async_validation
        if state is not None and asyncio.current_task() is state.runner_task:
            return state.initial
        return self._initial

    @initial.setter
    def initial(self, value):
        self._initial = value

    @property
    def fields(self):
        state = self._async_validation
        if state is not None and asyncio.current_task() is state.runner_task:
            return state.fields
        return self._fields

    @fields.setter
    def fields(self, value):
        self._fields = value

    @property
    def errors(self):
        """Return an ErrorDict for the data provided for the form."""
        # While an asynchronous validation round is in progress, only the
        # task running the round itself may observe the (possibly partial)
        # error collection. Every other caller gets a detached, empty
        # ErrorDict instead of a half-finished or stale result.
        state = self._async_validation
        if state is not None and asyncio.current_task() is not state.runner_task:
            return ErrorDict(renderer=self.renderer)
        if self._errors is None:
            self.full_clean()
        return self._errors

    @property
    def cleaned_data(self):
        state = self._async_validation
        if state is not None and asyncio.current_task() is not state.runner_task:
            # Never expose partially populated data to code outside the
            # task running the asynchronous validation round.
            return {}
        if self._cleaned_data is _UNSET:
            raise AttributeError(
                "'%s' object has no attribute 'cleaned_data'"
                % self.__class__.__name__
            )
        return self._cleaned_data

    @cleaned_data.setter
    def cleaned_data(self, value):
        self._cleaned_data = value

    def is_valid(self):
        """Return True if the form has no errors, or False otherwise."""
        return self.is_bound and not self.errors

    async def ais_valid(self):
        """
        Async counterpart of is_valid().

        Run the field and form cleaning pipeline asynchronously, awaiting
        any awaitable results returned by field validators, ``clean_<field>``
        hooks or the form-wide ``clean()`` hook. The business result, error
        attribution and error format match the synchronous path.

        Concurrent calls on the same form instance share a single cleaning
        round: side-effectful validators run only once, and callers joining
        later cannot change the inputs or outcome. If every waiting caller
        is cancelled, the unfinished round is discarded (including its
        temporary errors) and the next call performs a full retry.
        """
        state = self._async_validation
        if state is None:
            if self._can_reuse_validation():
                return self.is_bound and not self._errors
            state = self._start_async_validation()
        state.waiters += 1
        try:
            await asyncio.shield(state.runner_task)
        except asyncio.CancelledError:
            state.waiters -= 1
            if state.waiters == 0 and not state.finalized:
                # Every waiter has given up: abandon the unfinished round
                # synchronously so that a follow-up call starts a fresh one
                # even if the runner task has not processed its cancellation
                # yet.
                self._abandon_async_validation(state)
                state.runner_task.cancel()
            raise
        except BaseException:
            state.waiters -= 1
            raise
        state.waiters -= 1
        # Return the round's own conclusion rather than re-reading the live
        # form state: the form may have been re-validated or reset between
        # the runner finishing and this waiter resuming.
        return state.result

    def _validation_inputs(self):
        """The live (data, files, initial) a new round would clean."""
        return (self._data, self._files, self._initial)

    def _snapshot_validation_inputs(self):
        """Detached shallow copies of the live bound inputs."""
        data, files, initial = self._validation_inputs()
        return (
            _snapshot_mapping(data),
            _snapshot_mapping(files),
            dict(initial),
        )

    def _clone_field(self, field):
        """Detach a field definition without detaching its validators.

        The field object is shallow-copied and its mutable definition
        containers (validators, choices, error messages, widget, nested
        subfields) are copied, so reconfiguring the live field while a round
        is in progress cannot reach the runner. Validator callables -- which
        may be bound methods of the live form -- keep their identity.
        """
        clone = copy.copy(field)
        for attr, value in list(vars(clone).items()):
            if attr == "widget":
                clone.widget = copy.deepcopy(value)
            elif (
                attr == "fields"
                and isinstance(value, (list, tuple))
                and value
                and all(isinstance(sub, Field) for sub in value)
            ):
                cloned = [self._clone_field(sub) for sub in value]
                clone.fields = tuple(cloned) if isinstance(value, tuple) else cloned
            elif isinstance(value, list):
                setattr(clone, attr, list(value))
            elif isinstance(value, dict):
                setattr(clone, attr, dict(value))
            elif isinstance(value, set):
                setattr(clone, attr, set(value))
        return clone

    def _snapshot_fields(self):
        """A detached copy of the field definitions for an async round.

        Fields added, removed, replaced or reconfigured after the round
        starts -- validators appended to a field, choices mutated in place or
        a toggled ``required`` flag -- cannot reach the runner.
        """
        return {name: self._clone_field(field) for name, field in self._fields.items()}

    def _freeze_fingerprint_value(self, value):
        """Return an immutable snapshot of a fingerprint component.

        Mutable containers are copied so later in-place mutations (e.g.
        appending a validator or updating choices) change the live objects
        without retroactively changing the stored fingerprint.
        """
        if isinstance(value, (list, tuple)):
            return tuple(self._freeze_fingerprint_value(item) for item in value)
        if isinstance(value, set):
            return frozenset(self._freeze_fingerprint_value(item) for item in value)
        if isinstance(value, dict):
            return tuple(
                (key, self._freeze_fingerprint_value(item))
                for key, item in sorted(value.items(), key=lambda item: str(item[0]))
            )
        return value

    def _field_fingerprint(self, field):
        """Structural fingerprint of a field definition.

        Covers every instance attribute (validators, error messages,
        choices, input formats, coercion callables, subfields and so on) so
        that configuration changes invalidate a cached round. Mutable
        attributes are snapshotted; plain callables compare by identity.
        Nested subfields (ComboField / MultiValueField) and the widget are
        fingerprinted recursively.
        """
        items = []
        for key, value in vars(field).items():
            if (
                key == "fields"
                and isinstance(value, (list, tuple))
                and value
                and all(isinstance(sub, Field) for sub in value)
            ):
                value = tuple(self._field_fingerprint(sub) for sub in value)
            elif key == "widget":
                value = (
                    type(value),
                    self._freeze_fingerprint_value(vars(value)),
                )
            else:
                value = self._freeze_fingerprint_value(value)
            items.append((key, value))
        return tuple(sorted(items, key=lambda item: item[0]))

    def _fields_fingerprint(self, fields):
        return tuple(
            (name, self._field_fingerprint(field))
            for name, field in fields.items()
        )

    def _current_validation_fingerprint(self):
        """Fingerprint of the live inputs and the live field definitions."""
        data, files, initial = self._validation_inputs()
        return (
            _mapping_fingerprint(data),
            _mapping_fingerprint(files),
            tuple(sorted(initial.items(), key=lambda item: str(item[0]))),
            self._fields_fingerprint(self._fields),
        )

    def _can_reuse_validation(self):
        """Reuse a completed round when its fingerprint still matches."""
        if self._errors is None or self._validation_fingerprint is None:
            return False
        return self._current_validation_fingerprint() == self._validation_fingerprint

    def _start_async_validation(self):
        loop = asyncio.get_running_loop()
        inputs = self._snapshot_validation_inputs()
        fields = self._snapshot_fields()
        state = _AsyncValidationState(
            is_bound=self.is_bound,
            inputs=inputs,
            fields=fields,
            fingerprint=self._build_snapshot_fingerprint(inputs, fields),
        )
        # Capture the last successfully completed state so it can be
        # restored if this round is abandoned; a fresh form captures the
        # never-validated state (None / _UNSET).
        state.previous_errors = self._errors
        state.previous_cleaned_data = self._cleaned_data
        self._async_validation = state
        # The runner installs fresh staging collections as its first step.
        # Until then this task does not await anything, so the previous
        # collections cannot be observed mid-transition by another task.
        state.runner_task = loop.create_task(self._arun_async_validation(state))
        return state

    def _build_snapshot_fingerprint(self, inputs, fields):
        """Fingerprint matching _current_validation_fingerprint() for a
        detached round snapshot."""
        data, files, initial = inputs
        return (
            _mapping_fingerprint(data),
            _mapping_fingerprint(files),
            tuple(sorted(initial.items(), key=lambda item: str(item[0]))),
            self._fields_fingerprint(fields),
        )

    async def _arun_async_validation(self, state):
        # The round may already have been abandoned synchronously (every
        # waiter cancelled) before this task got its first step.
        if state.finalized:
            return
        completed = False
        try:
            await self._afull_clean(state)
            completed = True
        finally:
            # Finalization also runs if this task is cancelled before or
            # while the cleaning coroutine runs. A round abandoned directly
            # by the last waiter (or superseded by a newer round) is left
            # untouched.
            if self._async_validation is state and not state.finalized:
                if completed:
                    self._finish_async_validation(state)
                else:
                    self._abandon_async_validation(state)

    def _finish_async_validation(self, state):
        state.finalized = True
        state.result = state.is_bound and not self._errors
        self._validation_fingerprint = state.fingerprint
        self._async_validation = None

    def _abandon_async_validation(self, state):
        state.finalized = True
        state.result = False
        # Discard the temporary, possibly partial collections of this round
        # and expose the last successfully completed result (or the
        # never-validated state on a fresh form). No conclusion of this
        # round is cached: the fingerprint is cleared so the next call
        # performs a complete retry against the current inputs.
        self._errors = state.previous_errors
        self._cleaned_data = state.previous_cleaned_data
        self._validation_fingerprint = None
        self._async_validation = None

    def add_prefix(self, field_name):
        """
        Return the field name with a prefix appended, if this Form has a
        prefix set.

        Subclasses may wish to override.
        """
        return "%s-%s" % (self.prefix, field_name) if self.prefix else field_name

    def add_initial_prefix(self, field_name):
        """Add an 'initial' prefix for checking dynamic initial values."""
        return "initial-%s" % self.add_prefix(field_name)

    def _widget_data_value(self, widget, html_name):
        # value_from_datadict() gets the data from the data dictionaries.
        # Each widget type knows how to retrieve its own data, because some
        # widgets split data over several HTML fields.
        return widget.value_from_datadict(self.data, self.files, html_name)

    @property
    def template_name(self):
        return self.renderer.form_template_name

    def get_context(self):
        fields = []
        hidden_fields = []
        top_errors = self.non_field_errors().copy()
        for name, bf in self._bound_items():
            if bf.is_hidden:
                if bf.errors:
                    top_errors += [
                        _("(Hidden field %(name)s) %(error)s")
                        % {"name": name, "error": str(e)}
                        for e in bf.errors
                    ]
                hidden_fields.append(bf)
            else:
                fields.append((bf, bf.errors))
        return {
            "form": self,
            "fields": fields,
            "hidden_fields": hidden_fields,
            "errors": top_errors,
        }

    def non_field_errors(self):
        """
        Return an ErrorList of errors that aren't associated with a particular
        field -- i.e., from Form.clean(). Return an empty ErrorList if there
        are none.
        """
        return self.errors.get(
            NON_FIELD_ERRORS,
            self.error_class(error_class="nonfield", renderer=self.renderer),
        )

    def add_error(self, field, error):
        """
        Update the content of `self._errors`.

        The `field` argument is the name of the field to which the errors
        should be added. If it's None, treat the errors as NON_FIELD_ERRORS.

        The `error` argument can be a single error, a list of errors, or a
        dictionary that maps field names to lists of errors. An "error" can be
        either a simple string or an instance of ValidationError with its
        message attribute set and a "list or dictionary" can be an actual
        `list` or `dict` or an instance of ValidationError with its
        `error_list` or `error_dict` attribute set.

        If `error` is a dictionary, the `field` argument *must* be None and
        errors will be added to the fields that correspond to the keys of the
        dictionary.
        """
        if not isinstance(error, ValidationError):
            # Normalize to ValidationError and let its constructor
            # do the hard work of making sense of the input.
            error = ValidationError(error)

        if hasattr(error, "error_dict"):
            if field is not None:
                raise TypeError(
                    "The argument `field` must be `None` when the `error` "
                    "argument is a dictionary."
                )
            else:
                error = error.error_dict
        else:
            error = {field or NON_FIELD_ERRORS: error.error_list}

        for field, error_list in error.items():
            if field not in self.errors:
                if field != NON_FIELD_ERRORS and field not in self.fields:
                    raise ValueError(
                        "'%s' has no field named '%s'."
                        % (self.__class__.__name__, field)
                    )
                if field == NON_FIELD_ERRORS:
                    self._errors[field] = self.error_class(
                        error_class="nonfield", renderer=self.renderer
                    )
                else:
                    self._errors[field] = self.error_class(
                        renderer=self.renderer,
                        field_id=self[field].auto_id,
                    )
            self._errors[field].extend(error_list)
            if field in self.cleaned_data:
                del self.cleaned_data[field]

    def has_error(self, field, code=None):
        return field in self.errors and (
            code is None
            or any(error.code == code for error in self.errors.as_data()[field])
        )

    def full_clean(self):
        """
        Clean all of self.data and populate self._errors and self.cleaned_data.
        """
        self._errors = ErrorDict(renderer=self.renderer)
        if not self.is_bound:  # Stop further processing.
            self._record_validation_fingerprint()
            return
        self.cleaned_data = {}
        # If the form is permitted to be empty, and none of the form data has
        # changed from the initial data, short circuit any validation.
        if self.empty_permitted and not self.has_changed():
            self._record_validation_fingerprint()
            return

        self._clean_fields()
        self._clean_form()
        self._post_clean()
        self._record_validation_fingerprint()

    def _record_validation_fingerprint(self):
        # The synchronous path never consults the fingerprint itself (it
        # always re-runs), but it lets a later ais_valid() reuse the result.
        self._validation_fingerprint = self._current_validation_fingerprint()

    def _clean_fields(self):
        for name, bf in self._bound_items():
            field = bf.field
            try:
                self.cleaned_data[name] = field._clean_bound_field(bf)
                if hasattr(self, "clean_%s" % name):
                    value = getattr(self, "clean_%s" % name)()
                    self.cleaned_data[name] = value
            except ValidationError as e:
                self.add_error(name, e)

    def _async_raise_if_detached(self, state):
        """Stop a runner whose round was abandoned or superseded.

        A runner can keep running after cancellation if user code (a
        validator or a clean hook) swallows CancelledError. Such a detached
        runner must not write into the restored or newer form state, so it
        is re-cancelled at the next pipeline boundary.
        """
        if state.finalized or self._async_validation is not state:
            raise asyncio.CancelledError()

    async def _aclean_fields(self, state):
        for name, bf in self._bound_items():
            self._async_raise_if_detached(state)
            field = bf.field
            try:
                value = await field._aclean_bound_field(bf)
                # The value is written to cleaned_data only after any
                # awaitable field cleaning has resolved, so partial results
                # never persist.
                self._async_raise_if_detached(state)
                self.cleaned_data[name] = value
                if hasattr(self, "clean_%s" % name):
                    hook = getattr(self, "clean_%s" % name)
                    value = hook()
                    if inspect.isawaitable(value):
                        value = await value
                        self._async_raise_if_detached(state)
                    self.cleaned_data[name] = value
            except ValidationError as e:
                await self._aadd_error(name, e, state)

    def _clean_form(self):
        try:
            cleaned_data = self.clean()
        except ValidationError as e:
            self.add_error(None, e)
        else:
            if cleaned_data is not None:
                self.cleaned_data = cleaned_data

    async def _aclean_form(self, state):
        self._async_raise_if_detached(state)
        try:
            cleaned_data = self.clean()
            if inspect.isawaitable(cleaned_data):
                cleaned_data = await cleaned_data
                self._async_raise_if_detached(state)
        except ValidationError as e:
            await self._aadd_error(None, e, state)
        else:
            if cleaned_data is not None:
                self.cleaned_data = cleaned_data

    async def _apost_clean(self, state):
        """
        Async counterpart of _post_clean(). The default hook is a no-op, as
        on the synchronous path, and returns an awaitable result if a
        subclass's _post_clean() happens to produce one.
        """
        result = self._post_clean()
        if inspect.isawaitable(result):
            await result
            self._async_raise_if_detached(state)

    async def _afull_clean(self, state):
        """
        Async counterpart of full_clean(). Field cleaning runs in
        declaration order and the form-wide clean hook only reads field
        results that have already completed.
        """
        self._errors = ErrorDict(renderer=self.renderer)
        if not state.is_bound:  # Stop further processing.
            return
        self.cleaned_data = {}
        # If the form is permitted to be empty, and none of the form data has
        # changed from the initial data, short circuit any validation.
        if self.empty_permitted and not self.has_changed():
            return

        await self._aclean_fields(state)
        await self._aclean_form(state)
        await self._apost_clean(state)

    async def _aadd_error(self, field, error, state):
        self._async_raise_if_detached(state)
        result = self.add_error(field, error)
        if inspect.isawaitable(result):
            await result
            self._async_raise_if_detached(state)

    def _post_clean(self):
        """
        An internal hook for performing additional cleaning after form cleaning
        is complete. Used for model validation in model forms.
        """
        pass

    def clean(self):
        """
        Hook for doing any extra form-wide cleaning after Field.clean() has
        been called on every field. Any ValidationError raised by this method
        will not be associated with a particular field; it will have a
        special-case association with the field named '__all__'.
        """
        return self.cleaned_data

    def has_changed(self):
        """Return True if data differs from initial."""
        return bool(self.changed_data)

    @property
    def changed_data(self):
        state = self._async_validation
        if state is not None and asyncio.current_task() is state.runner_task:
            # Compute from the round snapshot without populating the shared
            # cache, which must stay tied to the live inputs.
            return [name for name, bf in self._bound_items() if bf._has_changed()]
        try:
            return self.__dict__["changed_data"]
        except KeyError:
            value = [name for name, bf in self._bound_items() if bf._has_changed()]
            self.__dict__["changed_data"] = value
            return value

    @changed_data.setter
    def changed_data(self, value):
        # Preserve cached_property's writable-instance-dict semantics.
        self.__dict__["changed_data"] = value

    @changed_data.deleter
    def changed_data(self):
        self.__dict__.pop("changed_data", None)

    @property
    def media(self):
        """Return all media required to render the widgets on this form."""
        media = Media()
        for field in self.fields.values():
            media += field.widget.media
        return media

    def is_multipart(self):
        """
        Return True if the form needs to be multipart-encoded, i.e. it has
        FileInput, or False otherwise.
        """
        return any(field.widget.needs_multipart_form for field in self.fields.values())

    def hidden_fields(self):
        """
        Return a list of all the BoundField objects that are hidden fields.
        Useful for manual form layout in templates.
        """
        return [field for field in self if field.is_hidden]

    def visible_fields(self):
        """
        Return a list of BoundField objects that aren't hidden fields.
        The opposite of the hidden_fields() method.
        """
        return [field for field in self if not field.is_hidden]

    def get_initial_for_field(self, field, field_name):
        """
        Return initial data for field on form. Use initial data from the form
        or the field, in that order. Evaluate callable values.
        """
        value = self.initial.get(field_name, field.initial)
        if callable(value):
            value = value()
        # If this is an auto-generated default date, nix the microseconds
        # for standardized handling. See #22502.
        if (
            isinstance(value, (datetime.datetime, datetime.time))
            and not field.widget.supports_microseconds
        ):
            value = value.replace(microsecond=0)
        return value


class Form(BaseForm, metaclass=DeclarativeFieldsMetaclass):
    "A collection of Fields, plus their associated data."

    # This is a separate class from BaseForm in order to abstract the way
    # self.fields is specified. This class (Form) is the one that does the
    # fancy metaclass stuff purely for the semantic sugar -- it allows one
    # to define a form using declarative syntax.
    # BaseForm itself has no way of designating self.fields.

import re

from django.core.exceptions import ValidationError
from django.forms.utils import RenderableFieldMixin, pretty_name
from django.forms.widgets import MultiWidget, Textarea, TextInput
from django.utils.functional import cached_property
from django.utils.html import format_html, html_safe
from django.utils.translation import gettext_lazy as _

__all__ = ("BoundField",)


class BoundField(RenderableFieldMixin):
    "A Field plus data"

    def __init__(self, form, field, name):
        self.form = form
        self.field = field
        self.name = name
        self.html_name = form.add_prefix(name)
        self.html_initial_name = form.add_initial_prefix(name)
        self.html_initial_id = form.add_initial_prefix(self.auto_id)
        if self.field.label is None:
            self.label = pretty_name(name)
        else:
            self.label = self.field.label
        self.help_text = field.help_text or ""
        self.renderer = form.renderer

    @cached_property
    def subwidgets(self):
        """
        Most widgets yield a single subwidget, but others like RadioSelect and
        CheckboxSelectMultiple produce one subwidget for each choice.

        This property is cached so that only one database query occurs when
        rendering ModelChoiceFields.
        """
        id_ = self.field.widget.attrs.get("id") or self.auto_id
        attrs = {"id": id_} if id_ else {}
        attrs = self.build_widget_attrs(attrs)
        return [
            BoundWidget(self.field.widget, widget, self.form.renderer)
            for widget in self.field.widget.subwidgets(
                self.html_name, self.value(), attrs=attrs
            )
        ]

    def __bool__(self):
        # BoundField evaluates to True even if it doesn't have subwidgets.
        return True

    def __iter__(self):
        return iter(self.subwidgets)

    def __len__(self):
        return len(self.subwidgets)

    def __getitem__(self, idx):
        # Prevent unnecessary reevaluation when accessing BoundField's attrs
        # from templates.
        if not isinstance(idx, (int, slice)):
            raise TypeError(
                "BoundField indices must be integers or slices, not %s."
                % type(idx).__name__
            )
        return self.subwidgets[idx]

    @property
    def errors(self):
        """
        Return an ErrorList (empty if there are no errors) for this field.
        """
        return self.form.errors.get(
            self.name, self.form.error_class(renderer=self.form.renderer)
        )

    @property
    def template_name(self):
        return self.field.template_name or self.form.renderer.field_template_name

    def get_context(self):
        return {"field": self}

    def as_widget(self, widget=None, attrs=None, only_initial=False):
        """
        Render the field by rendering the passed widget, adding any HTML
        attributes passed as attrs. If a widget isn't specified, use the
        field's default widget.
        """
        widget = widget or self.field.widget
        if self.field.localize:
            widget.is_localized = True
        attrs = attrs or {}
        attrs = self.build_widget_attrs(attrs, widget)
        if self.auto_id and "id" not in widget.attrs:
            attrs.setdefault(
                "id", self.html_initial_id if only_initial else self.auto_id
            )
        if only_initial and self.html_initial_name in self.form.data:
            # Propagate the hidden initial value.
            value = self.form._widget_data_value(
                self.field.hidden_widget(),
                self.html_initial_name,
            )
        else:
            value = self.value()
        return widget.render(
            name=self.html_initial_name if only_initial else self.html_name,
            value=value,
            attrs=attrs,
            renderer=self.form.renderer,
        )

    def as_text(self, attrs=None, **kwargs):
        """
        Return a string of HTML for representing this as an
        <input type="text">.
        """
        return self.as_widget(TextInput(), attrs, **kwargs)

    def as_textarea(self, attrs=None, **kwargs):
        """Return a string of HTML for representing this as a <textarea>."""
        return self.as_widget(Textarea(), attrs, **kwargs)

    def as_hidden(self, attrs=None, **kwargs):
        """
        Return a string of HTML for representing this as an
        <input type="hidden">.
        """
        return self.as_widget(self.field.hidden_widget(), attrs, **kwargs)

    @property
    def data(self):
        """
        Return the data for this BoundField, or None if it wasn't given.
        """
        return self.form._widget_data_value(self.field.widget, self.html_name)

    def value(self):
        """
        Return the value for this BoundField, using the initial value if
        the form is not bound or the data otherwise.
        """
        data = self.initial
        if self.form.is_bound:
            data = self.field.bound_data(self.data, data)
        return self.field.prepare_value(data)

    def _has_changed(self):
        field = self.field
        if field.show_hidden_initial:
            hidden_widget = field.hidden_widget()
            initial_value = self.form._widget_data_value(
                hidden_widget,
                self.html_initial_name,
            )
            try:
                initial_value = field.to_python(initial_value)
            except ValidationError:
                # Always assume data has changed if validation fails.
                return True
        else:
            initial_value = self.initial
        return field.has_changed(initial_value, self.data)

    def label_tag(self, contents=None, attrs=None, label_suffix=None, tag=None):
        """
        Wrap the given contents in a <label>, if the field has an ID attribute.
        contents should be mark_safe'd to avoid HTML escaping. If contents
        aren't given, use the field's HTML-escaped label.

        If attrs are given, use them as HTML attributes on the <label> tag.

        label_suffix overrides the form's label_suffix.
        """
        contents = contents or self.label
        if label_suffix is None:
            label_suffix = (
                self.field.label_suffix
                if self.field.label_suffix is not None
                else self.form.label_suffix
            )
        # Only add the suffix if the label does not end in punctuation.
        # Translators: If found as last label character, these punctuation
        # characters will prevent the default label_suffix to be appended to
        # the label
        if label_suffix and contents and contents[-1] not in _(":?.!"):
            contents = format_html("{}{}", contents, label_suffix)
        widget = self.field.widget
        id_ = widget.attrs.get("id") or self.auto_id
        if id_:
            id_for_label = widget.id_for_label(id_)
            if id_for_label:
                attrs = attrs or {}
                if tag != "legend":
                    attrs = {**attrs, "for": id_for_label}
            if self.field.required and hasattr(self.form, "required_css_class"):
                attrs = attrs or {}
                if "class" in attrs:
                    attrs["class"] += " " + self.form.required_css_class
                else:
                    attrs["class"] = self.form.required_css_class
        context = {
            "field": self,
            "label": contents,
            "attrs": attrs,
            "use_tag": bool(id_),
            "tag": tag or "label",
        }
        return self.form.render(self.form.template_name_label, context)

    def legend_tag(self, contents=None, attrs=None, label_suffix=None):
        """
        Wrap the given contents in a <legend>, if the field has an ID
        attribute. Contents should be mark_safe'd to avoid HTML escaping. If
        contents aren't given, use the field's HTML-escaped label.

        If attrs are given, use them as HTML attributes on the <legend> tag.

        label_suffix overrides the form's label_suffix.
        """
        return self.label_tag(contents, attrs, label_suffix, tag="legend")

    def css_classes(self, extra_classes=None):
        """
        Return a string of space-separated CSS classes for this field.
        """
        if hasattr(extra_classes, "split"):
            extra_classes = extra_classes.split()
        extra_classes = set(extra_classes or [])
        if self.errors and hasattr(self.form, "error_css_class"):
            extra_classes.add(self.form.error_css_class)
        if self.field.required and hasattr(self.form, "required_css_class"):
            extra_classes.add(self.form.required_css_class)
        return " ".join(extra_classes)

    @property
    def is_hidden(self):
        """Return True if this BoundField's widget is hidden."""
        return self.field.widget.is_hidden

    @property
    def auto_id(self):
        """
        Calculate and return the ID attribute for this BoundField, if the
        associated Form has specified auto_id. Return an empty string
        otherwise.
        """
        auto_id = self.form.auto_id  # Boolean or string
        if auto_id and "%s" in str(auto_id):
            return auto_id % self.html_name
        elif auto_id:
            return self.html_name
        return ""

    @property
    def id_for_label(self):
        """
        Wrapper around the field widget's `id_for_label` method.
        Useful, for example, for focusing on this field regardless of whether
        it has a single widget or a MultiWidget.
        """
        widget = self.field.widget
        id_ = widget.attrs.get("id") or self.auto_id
        return widget.id_for_label(id_)

    @cached_property
    def initial(self):
        return self.form.get_initial_for_field(self.field, self.name)

    def build_widget_attrs(self, attrs, widget=None):
        widget = widget or self.field.widget
        attrs = dict(attrs)  # Copy attrs to avoid modifying the argument.
        if (
            widget.use_required_attribute(self.initial)
            and self.field.required
            and self.form.use_required_attribute
        ):
            # MultiValueField has require_all_fields: if False, fall back
            # on subfields.
            if (
                hasattr(self.field, "require_all_fields")
                and not self.field.require_all_fields
                and isinstance(self.field.widget, MultiWidget)
            ):
                for subfield, subwidget in zip(self.field.fields, widget.widgets):
                    subwidget.attrs["required"] = (
                        subwidget.use_required_attribute(self.initial)
                        and subfield.required
                    )
            else:
                attrs["required"] = True
        if self.field.disabled:
            attrs["disabled"] = True
        if not widget.is_hidden and self.errors:
            attrs["aria-invalid"] = "true"
        # Preserve aria-describedby provided by the attrs argument so user
        # can set the desired order.
        if not attrs.get("aria-describedby") and not self.use_fieldset:
            if aria_describedby := self.aria_describedby:
                attrs["aria-describedby"] = aria_describedby
        return attrs

    @property
    def aria_describedby(self):
        # Preserve aria-describedby set on the widget.
        if self.field.widget.attrs.get("aria-describedby"):
            return None
        aria_describedby = []
        if self.auto_id and not self.is_hidden:
            if self.help_text:
                aria_describedby.append(f"{self.auto_id}_helptext")
            if self.errors:
                aria_describedby.append(f"{self.auto_id}_error")
        return " ".join(aria_describedby)

    @property
    def widget_type(self):
        return re.sub(
            r"widget$|input$", "", self.field.widget.__class__.__name__.lower()
        )

    @property
    def use_fieldset(self):
        """
        Return the value of this BoundField widget's use_fieldset attribute.
        """
        return self.field.widget.use_fieldset


@html_safe
class BoundWidget:
    """
    A container class used for iterating over widgets. This is useful for
    widgets that have choices. For example, the following can be used in a
    template:

    {% for radio in myform.beatles %}
      <label for="{{ radio.id_for_label }}">
        {{ radio.choice_label }}
        <span class="radio">{{ radio.tag }}</span>
      </label>
    {% endfor %}
    """

    def __init__(self, parent_widget, data, renderer):
        self.parent_widget = parent_widget
        self.data = data
        self.renderer = renderer

    def __str__(self):
        return self.tag(wrap_label=True)

    def tag(self, wrap_label=False):
        context = {"widget": {**self.data, "wrap_label": wrap_label}}
        return self.parent_widget._render(self.template_name, context, self.renderer)

    @property
    def template_name(self):
        if "template_name" in self.data:
            return self.data["template_name"]
        return self.parent_widget.template_name

    @property
    def id_for_label(self):
        return self.data["attrs"].get("id")

    @property
    def choice_label(self):
        return self.data["label"]

    def run_validators(self, value):
        if value in self.empty_values:
            return
        errors = []
        for v in self.validators:
            try:
                v(value)
            except ValidationError as e:
                if hasattr(e, "code") and e.code in self.error_messages:
                    e.message = self.error_messages[e.code]
                errors.extend(e.error_list)
        if errors:
            raise ValidationError(errors)

    async def arun_validators(self, value):
        """Async counterpart of run_validators().

        Each validator is called in declaration order; a validator that
        returns an awaitable result is awaited before the next validator
        runs. ValidationErrors are collected exactly like the synchronous
        path; any other exception propagates immediately.
        """
        if value in self.empty_values:
            return
        errors = []
        for v in self.validators:
            try:
                result = v(value)
                if inspect.isawaitable(result):
                    await result
            except ValidationError as e:
                if hasattr(e, "code") and e.code in self.error_messages:
                    e.message = self.error_messages[e.code]
                errors.extend(e.error_list)
        if errors:
            raise ValidationError(errors)

    def clean(self, value):
        """
        Validate the given value and return its "cleaned" value as an
        appropriate Python object. Raise ValidationError for any errors.
        """
        value = self.to_python(value)
        self.validate(value)
        self.run_validators(value)
        return value

    async def aclean(self, value):
        """
        Async counterpart of clean().

        A subclass that overrides clean() with a coroutine function is
        awaited directly; otherwise the synchronous to_python/validate
        stages run unchanged and validators are dispatched through the
        async pipeline, preserving declaration order and error handling.
        """
        if inspect.iscoroutinefunction(self.clean):
            return await self.clean(value)
        value = self.to_python(value)
        if inspect.isawaitable(value):
            value = await value
        validation = self.validate(value)
        if inspect.isawaitable(validation):
            await validation
        await self.arun_validators(value)
        return value

    def bound_data(self, data, initial):
        """
        Return the value that should be shown for this field on render of a
        bound form, given the submitted POST data for the field and the initial
        data, if any.

        For most fields, this will simply be data; FileFields need to handle it
        a bit differently.
        """
        if self.disabled:
            return initial
        return data

    def widget_attrs(self, widget):
        """
        Given a Widget instance (*not* a Widget class), return a dictionary of
        any HTML attributes that should be added to the Widget, based on this
        Field.
        """
        return {}

    def has_changed(self, initial, data):
        """Return True if data differs from initial."""
        # Always return False if the field is disabled since self.bound_data
        # always uses the initial value in this case.
        if self.disabled:
            return False
        try:
            data = self.to_python(data)
            if hasattr(self, "_coerce"):
                return self._coerce(data) != self._coerce(initial)
        except ValidationError:
            return True
        # For purposes of seeing whether something has changed, None is
        # the same as an empty string, if the data or initial value we get
        # is None, replace it with ''.
        initial_value = initial if initial is not None else ""
        data_value = data if data is not None else ""
        return initial_value != data_value

    def get_bound_field(self, form, field_name):
        """
        Return a BoundField instance that will be used when accessing the form
        field in a template.
        """
        bound_field_class = (
            self.bound_field_class or form.bound_field_class or BoundField
        )
        return bound_field_class(form, self, field_name)

    def __deepcopy__(self, memo):
        result = copy.copy(self)
        memo[id(self)] = result
        result.widget = copy.deepcopy(self.widget, memo)
        result.error_messages = self.error_messages.copy()
        result.validators = self.validators[:]
        return result

    def _clean_bound_field(self, bf):
        value = bf.initial if self.disabled else bf.data
        return self.clean(value)

    async def _aclean_bound_field(self, bf):
        value = bf.initial if self.disabled else bf.data
        return await self.aclean(value)


class CharField(Field):
    def __init__(
        self, *, max_length=None, min_length=None, strip=True, empty_value="", **kwargs
    ):
        self.max_length = max_length
        self.min_length = min_length

    def __init__(self, *, max_length=None, allow_empty_file=False, **kwargs):
        self.max_length = max_length
        self.allow_empty_file = allow_empty_file
        super().__init__(**kwargs)

    def to_python(self, data):
        if data in self.empty_values:
            return None

        # UploadedFile objects should have name and size attributes.
        try:
            file_name = data.name
            file_size = data.size
        except AttributeError:
            raise ValidationError(self.error_messages["invalid"], code="invalid")

        if self.max_length is not None and len(file_name) > self.max_length:
            params = {"max": self.max_length, "length": len(file_name)}
            raise ValidationError(
                self.error_messages["max_length"], code="max_length", params=params
            )
        if not file_name:
            raise ValidationError(self.error_messages["invalid"], code="invalid")
        if not self.allow_empty_file and not file_size:
            raise ValidationError(self.error_messages["empty"], code="empty")

        return data

    def clean(self, data, initial=None):
        # If the widget got contradictory inputs, we raise a validation error
        if data is FILE_INPUT_CONTRADICTION:
            raise ValidationError(
                self.error_messages["contradiction"], code="contradiction"
            )
        # False means the field value should be cleared; further validation is
        # not needed.
        if data is False:
            if not self.required:
                return False
            # If the field is required, clearing is not possible (the widget
            # shouldn't return False data in that case anyway). False is not
            # in self.empty_value; if a False value makes it this far
            # it should be validated from here on out as None (so it will be
            # caught by the required check).
            data = None
        if not data and initial:
            return initial
        return super().clean(data)

    async def aclean(self, data, initial=None):
        if inspect.iscoroutinefunction(self.clean):
            return await self.clean(data, initial)
        # Mirror the synchronous preprocessing of clean() before dispatching
        # through the async field pipeline.
        if data is FILE_INPUT_CONTRADICTION:
            raise ValidationError(
                self.error_messages["contradiction"], code="contradiction"
            )
        if data is False:
            if not self.required:
                return False
            data = None
        if not data and initial:
            return initial
        return await super().aclean(data)

    def bound_data(self, _, initial):
        return initial

    def has_changed(self, initial, data):
        return not self.disabled and data is not None

    def _clean_bound_field(self, bf):
        value = bf.initial if self.disabled else bf.data
        return self.clean(value, bf.initial)

    async def _aclean_bound_field(self, bf):
        value = bf.initial if self.disabled else bf.data
        return await self.aclean(value, bf.initial)


class ImageField(FileField):
    default_validators = [validators.validate_image_file_extension]
    default_error_messages = {
